{"path": "poker.py", "content": "from collections import Counter

RANKS = {r: i for i, r in enumerate("23456789", 2)}
RANKS.update({"10": 10, "J": 11, "Q": 12, "K": 13, "A": 14})


def _score(hand):
    cards = hand.split()
    ranks = [RANKS[c[:-1]] for c in cards]
    flush = len({c[-1] for c in cards}) == 1
    counts = Counter(ranks)
    ordered = sorted(counts, key=lambda r: (counts[r], r), reverse=True)
    shape = sorted(counts.values(), reverse=True)
    if sorted(ranks) == [2, 3, 4, 5, 14]:
        ordered = [5, 4, 3, 2, 1]
    straight = len(counts) == 5 and ordered[0] - ordered[-1] == 4
    if straight and flush:
        cat = 8
    elif shape == [4, 1]:
        cat = 7
    elif shape == [3, 2]:
        cat = 6
    elif flush:
        cat = 5
    elif straight:
        cat = 4
    elif shape == [3, 1, 1]:
        cat = 3
    elif shape == [2, 2, 1]:
        cat = 2
    elif shape == [2, 1, 1, 1]:
        cat = 1
    else:
        cat = 0
    return (cat, ordered)


def best_hands(hands):
    scores = [_score(h) for h in hands]
    best = max(scores)
    return [h for h, s in zip(hands, scores) if s == best]
